// Blog posts aren't in the i18n dictionaries (src/i18n/fr.json /en.json) —
// they live in src/content/blogPosts.js as a per-post { en, fr } object with
// a body that's an array of paragraphs. getBlogPostSchema() describes the
// same three fields (title, excerpt, body) for every post, as flat
// content_overrides keys. See src/content/blogContent.js for how an override
// is merged back onto a post, and src/pages/BlogPost.jsx / Blog.jsx for
// where that merged post is rendered.
export const BLOG_POSTS = [
  {
    "slug": "managing-anxiety",
    "label": "Five grounding techniques for anxiety"
  },
  {
    "slug": "couple-therapy",
    "label": "What really happens in couple therapy"
  },
  {
    "slug": "navigating-grief",
    "label": "Navigating grief"
  }
]

export function getBlogPostSchema() {
  return {
    page: 'blogPosts',
    pageLabel: 'Blog posts (text for each article)',
    fields: BLOG_POSTS.flatMap(({ slug, label }) => [
      { key: `blog.${slug}.title`, label: `${label} — Title`, multiline: false },
      { key: `blog.${slug}.excerpt`, label: `${label} — Excerpt (shown in the list)`, multiline: true },
      { key: `blog.${slug}.body`, label: `${label} — Full text (one paragraph per blank line)`, multiline: true },
    ]),
  }
}

// The full schema: every i18n-backed field plus the blog post fields.
export function getContentSchema() {
  return [...CONTENT_SCHEMA, getBlogPostSchema()]
}

export function findFieldLabel(key) {
  for (const group of getContentSchema()) {
    const field = group.fields.find((f) => f.key === key)
    if (field) return field.label
  }
  return key
}
